from pathlib import Path
p=Path('artifacts/project-ice/public/world.js')
s=p.read_text()
old="""    while (\n      nextDate < targetDate &&\n      daysAdvanced < maximumDays\n    ) {\n      const advancedDate =\n        advanceDay({\n          save: false,\n        });\n\n      if (!advancedDate) {\n        break;\n      }\n\n      nextDate =\n        advancedDate;\n\n      const dateProcessingResult =\n        processSeasonDate(\n          advancedDate,\n          {\n            save: false,\n          }\n        );\n\n      dateProcessingResults.push(\n        dateProcessingResult\n      );\n\n      daysAdvanced += 1;\n\n      const enteredWeek =\n        Math.max(\n          1,\n          Number(\n            _state.season?.currentWeek ??\n            _state.currentWeek\n          ) || activeWeek\n        );\n\n      /*\n       * Process a completed week at the moment its boundary is\n       * crossed. This is essential when Sim To Date spans several\n       * weeks: each snapshot must reflect that week's real state,\n       * not the final state at the end of the entire skip.\n       *\n       * The new day's scheduled event is resolved first, so results\n       * on that date are canonical before any presentation reads the\n       * world again. A blocking interaction still preserves the week\n       * boundary because the calendar has genuinely entered it.\n       */\n      if (enteredWeek > activeWeek) {\n        const enteredWeeks = [];\n\n        for (\n          let week = activeWeek + 1;\n          week <= enteredWeek;\n          week++\n        ) {\n          enteredWeeks.push(week);\n          crossedWeeks.push(week);\n        }\n\n        const boundaryResults =\n          processCrossedSeasonWeeks(\n            enteredWeeks,\n            {\n              save: false,\n              completedAtDate:\n                advancedDate,\n            }\n          );\n\n        weeklyProcessingResults.push(\n          ...boundaryResults\n        );\n\n        activeWeek = enteredWeek;\n      }\n\n      if (\n        dateProcessingResult\n          ?.stopSimulation === true\n      ) {"""
new="""    while (\n      nextDate < targetDate &&\n      daysAdvanced < maximumDays\n    ) {\n      const previousDate =\n        nextDate;\n\n      const advancedDate =\n        advanceDay({\n          save: false,\n        });\n\n      if (!advancedDate) {\n        break;\n      }\n\n      nextDate =\n        advancedDate;\n\n      const enteredWeek =\n        Math.max(\n          1,\n          Number(\n            _state.season?.currentWeek ??\n            _state.currentWeek\n          ) || activeWeek\n        );\n\n      /*\n       * Entering a new week closes the previous one BEFORE events\n       * on the new week's first date are resolved. That keeps each\n       * snapshot historically exact: Week N contains only results\n       * through the final date of Week N, even when Sim To Date\n       * crosses several boundaries in one request.\n       */\n      if (enteredWeek > activeWeek) {\n        const enteredWeeks = [];\n\n        for (\n          let week = activeWeek + 1;\n          week <= enteredWeek;\n          week++\n        ) {\n          enteredWeeks.push(week);\n          crossedWeeks.push(week);\n        }\n\n        const boundaryResults =\n          processCrossedSeasonWeeks(\n            enteredWeeks,\n            {\n              save: false,\n              completedAtDate:\n                previousDate,\n            }\n          );\n\n        weeklyProcessingResults.push(\n          ...boundaryResults\n        );\n\n        activeWeek = enteredWeek;\n      }\n\n      const dateProcessingResult =\n        processSeasonDate(\n          advancedDate,\n          {\n            save: false,\n          }\n        );\n\n      dateProcessingResults.push(\n        dateProcessingResult\n      );\n\n      daysAdvanced += 1;\n\n      if (\n        dateProcessingResult\n          ?.stopSimulation === true\n      ) {"""
if old not in s: raise SystemExit('boundary block not found')
p.write_text(s.replace(old,new,1))
print('Fixed weekly boundary ordering')
